import{_ as a,y as i,a as d,o as l,g as e,D as r,a2 as n,I as o}from"./chunks/framework.DCcmcJcL.js";const w=JSON.parse('{"title":"Customers","description":"","frontmatter":{},"headers":[],"relativePath":"customer/create-customer.md","filePath":"customer/create-customer.md","lastUpdated":1789441803000}'),h={name:"customer/create-customer.md"};function g(c,t,u,m,p,f){const s=i("ImagePopup");return l(),d("div",null,[t[4]||(t[4]=e("h1",{id:"customers",tabindex:"-1"},[o("Customers "),e("a",{class:"header-anchor",href:"#customers","aria-label":'Permalink to "Customers"'},"​")],-1)),t[5]||(t[5]=e("p",null,[o("Customers are shoppers with an account in your store. Most sign up on the storefront, but you can also create an account for someone in the admin panel, for example when they order by phone. From "),e("strong",null,"Customers >> Customers"),o(" you can find any customer, open their page to see their orders, invoices, reviews, notes and addresses, and change their account.")],-1)),t[6]||(t[6]=e("h2",{id:"the-customers-list",tabindex:"-1"},[o("The customers list "),e("a",{class:"header-anchor",href:"#the-customers-list","aria-label":'Permalink to "The customers list"'},"​")],-1)),t[7]||(t[7]=e("p",null,[o("Go to "),e("strong",null,"Customers >> Customers"),o(".")],-1)),r(s,{src:"/images/customer/customer-grid.png",alt:"The customers list under Customers >> Customers"}),t[8]||(t[8]=n('<p>Each row shows three columns:</p><ul><li><strong>Customer Name / Email / Contact Number</strong>: <strong>N/A</strong> when the customer has no phone number.</li><li><strong>Status / Gender / Group / Customer ID / Channel</strong>: an <strong>Active</strong> or <strong>Inactive</strong> badge, with a <strong>Suspended</strong> badge when the account is suspended, then the gender, the customer group, the channel the account belongs to and the customer&#39;s ID.</li><li><strong>Revenue / Order Count / Address Count</strong>: the invoiced total of the customer&#39;s orders, not counting canceled and closed orders, then the number of orders and of saved addresses.</li></ul><h3 id="find-customers" tabindex="-1">Find customers <a class="header-anchor" href="#find-customers" aria-label="Permalink to &quot;Find customers&quot;">​</a></h3><ul><li><strong>Search:</strong> type in the search box to find customers by name or email.</li><li><strong>Filter:</strong> click <strong>Filter</strong> and filter by <strong>Channel</strong>, <strong>Customer ID</strong>, <strong>Customer Name</strong>, <strong>Email</strong>, <strong>Contact Number</strong>, <strong>Status</strong> or <strong>Group</strong>.</li><li><strong>Sort:</strong> click <strong>Customer Name</strong>, <strong>Email</strong>, <strong>Status</strong>, <strong>Gender</strong>, <strong>Channel</strong>, <strong>Order Count</strong> or <strong>Address Count</strong> in the header row.</li></ul><h3 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h3><ul><li><strong>Login as customer</strong> (the sign-in icon) opens the storefront in a new tab, signed in as the customer. See <a href="#sign-in-as-the-customer">Sign in as the customer</a>.</li><li><strong>View</strong> (the arrow) opens the customer&#39;s page.</li></ul><h3 id="change-several-customers-at-once" tabindex="-1">Change several customers at once <a class="header-anchor" href="#change-several-customers-at-once" aria-label="Permalink to &quot;Change several customers at once&quot;">​</a></h3><ol><li>Go to <strong>Customers &gt;&gt; Customers</strong>.</li><li>Tick the customers.</li><li>Open <strong>Select Action</strong>.</li><li>Choose <strong>Delete</strong>, or point to <strong>Update Status</strong> and choose <strong>Active</strong> or <strong>Inactive</strong>.</li></ol><p>A customer with an order that&#39;s still <strong>Pending</strong> or <strong>Processing</strong> can&#39;t be deleted. If any of the ticked customers has one, none of them is deleted. Deleting a customer can&#39;t be undone.</p><h3 id="export-the-list" tabindex="-1">Export the list <a class="header-anchor" href="#export-the-list" aria-label="Permalink to &quot;Export the list&quot;">​</a></h3><ol><li>Go to <strong>Customers &gt;&gt; Customers</strong>.</li><li>Click <strong>Export</strong>.</li><li>Choose <strong>CSV</strong>, <strong>XLS</strong> or <strong>XLSX</strong>.</li><li>Click <strong>Export</strong>.</li></ol><p>The file lists the customers with their details, without the <strong>Revenue</strong> column.</p><h2 id="create-a-customer" tabindex="-1">Create a customer <a class="header-anchor" href="#create-a-customer" aria-label="Permalink to &quot;Create a customer&quot;">​</a></h2>',13)),e("ol",null,[t[1]||(t[1]=e("li",null,[e("p",null,[o("Go to "),e("strong",null,"Customers >> Customers"),o(".")])],-1)),t[2]||(t[2]=e("li",null,[e("p",null,[o("Click "),e("strong",null,"Create Customer"),o(". The "),e("strong",null,"Create New Customer"),o(" dialog opens.")])],-1)),e("li",null,[t[0]||(t[0]=e("p",null,"Fill in the fields described in the table below.",-1)),r(s,{src:"/images/customer/create-customer.png",alt:"Create New Customer dialog with the name, email, phone, date of birth, gender, channel and group filled in"})]),t[3]||(t[3]=e("li",null,[e("p",null,[o("Click "),e("strong",null,"Save customer"),o(". The customer is added to the list.")])],-1))]),t[9]||(t[9]=n('<table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>First Name</strong> and <strong>Last Name</strong></td><td>The customer&#39;s name. Both are required.</td></tr><tr><td><strong>Email</strong></td><td>Required. The customer signs in with it, and it can belong to only one account in a channel.</td></tr><tr><td><strong>Contact Number</strong></td><td>Optional. A phone number can belong to only one customer.</td></tr><tr><td><strong>Date of Birth</strong></td><td>Optional. It must be before today.</td></tr><tr><td><strong>Gender</strong></td><td>Required: <strong>Male</strong>, <strong>Female</strong> or <strong>Other</strong>.</td></tr><tr><td><strong>Channel</strong></td><td>Required. The channel the account belongs to. The customer signs in on that channel&#39;s storefront, and you can&#39;t change the channel later.</td></tr><tr><td><strong>Customer Group</strong></td><td>The group, which decides the group prices and promotions the customer gets. See <a href="./customer-group.html">Customer Groups</a>.</td></tr></tbody></table><p>To add many customers at once, see <a href="./../settings/data-transfer.html">Data Transfer</a>.</p><h3 id="the-account-password" tabindex="-1">The account password <a class="header-anchor" href="#the-account-password" aria-label="Permalink to &quot;The account password&quot;">​</a></h3><p>The dialog has no password field. Bagisto gives the account a random password and marks its email address as verified, so the customer doesn&#39;t have to verify it.</p><ul><li>When <strong>Send the customer account credentials after registration</strong> is on in <a href="./../configure/notifications.html">Notifications</a>, the customer receives an email with their sign-in details.</li><li>When it&#39;s off, ask the customer to click <strong>Forgot Password?</strong> on the sign-in page to set their own password.</li></ul><p>When <strong>Send a confirmation e-mail to admin after customer registration</strong> is on, the admin also receives an email about the new account.</p><h2 id="the-customer-page" tabindex="-1">The customer page <a class="header-anchor" href="#the-customer-page" aria-label="Permalink to &quot;The customer page&quot;">​</a></h2><p>Click the arrow on a customer&#39;s row to open their page. The title shows the customer&#39;s name with an <strong>Active</strong> or <strong>Inactive</strong> badge, and a <strong>Suspended</strong> badge when the account is suspended. <strong>Back</strong> returns to the customers list.</p>',8)),r(s,{src:"/images/customer/customer-view.png",alt:"A customer's page with the Create Order, Login as customer and Delete Account actions, the Orders, Invoices and Reviews cards, and the Customer and Addresses cards"}),t[10]||(t[10]=n('<p>Below the title are three actions. Under them, the <strong>Orders</strong>, <strong>Invoices</strong>, <strong>Reviews</strong> and <strong>Add Note</strong> cards are on the left, and the <strong>Customer</strong> and <strong>Addresses</strong> cards are on the right.</p><h3 id="create-an-order-for-the-customer" tabindex="-1">Create an order for the customer <a class="header-anchor" href="#create-an-order-for-the-customer" aria-label="Permalink to &quot;Create an order for the customer&quot;">​</a></h3><ol><li>Click <strong>Create Order</strong>.</li><li>Click <strong>Agree</strong> to confirm. The <strong>Create Order for</strong> page opens for the customer.</li><li>Add the products and complete the order as described in <a href="./../orders/create-order.html#add-products">Create Order</a>.</li></ol><p><strong>Create Order</strong> appears only when your role is allowed to create orders.</p><h3 id="sign-in-as-the-customer" tabindex="-1">Sign in as the customer <a class="header-anchor" href="#sign-in-as-the-customer" aria-label="Permalink to &quot;Sign in as the customer&quot;">​</a></h3><p><strong>Login as customer</strong> opens the storefront in a new tab, signed in as the customer, on their <strong>Profile</strong> page. Use it to see the account the way the customer does, for example to help them find an order.</p><div class="warning custom-block"><p class="custom-block-title">You act as the customer</p><p>While you&#39;re signed in this way, anything you do on the storefront, such as placing an order or changing the profile, is done in the customer&#39;s name. Sign out on the storefront when you&#39;ve finished.</p></div><p>The action appears only when your role has the <strong>Login As Customer</strong> permission.</p><h3 id="delete-the-account" tabindex="-1">Delete the account <a class="header-anchor" href="#delete-the-account" aria-label="Permalink to &quot;Delete the account&quot;">​</a></h3><ol><li>Click <strong>Delete Account</strong>.</li><li>Click <strong>Agree</strong> to confirm.</li></ol><p>An account with an order that&#39;s still <strong>Pending</strong> or <strong>Processing</strong> can&#39;t be deleted: the page shows <em>This customer has pending orders and cannot be deleted.</em> Complete or cancel those orders first. The customer&#39;s orders stay under <strong>Sales &gt;&gt; Orders</strong> after the account is deleted. Deleting an account can&#39;t be undone.</p><h3 id="orders-invoices-and-reviews" tabindex="-1">Orders, invoices and reviews <a class="header-anchor" href="#orders-invoices-and-reviews" aria-label="Permalink to &quot;Orders, invoices and reviews&quot;">​</a></h3><ul><li><strong>Orders</strong> shows how many orders the customer has placed and the <strong>Total Revenue</strong>, the invoiced total without canceled and closed orders. Each row shows the order number, date and status, the grand total, payment method and channel, and the billing name, email and location. The arrow opens the order.</li><li><strong>Invoices</strong> lists the customer&#39;s invoices with the <strong>Invoices ID</strong>, <strong>Invoices Date</strong>, <strong>Invoices Amount</strong> and <strong>Order ID</strong>. The arrow opens the invoice.</li><li><strong>Reviews</strong> lists the customer&#39;s product reviews with the product, status, title, comment, rating and date. The arrow opens the product&#39;s edit screen in a new tab. To approve a review, see <a href="./customer-review.html">Customer Reviews</a>.</li></ul><p>Each card has its own search box, filters and pages, like the main lists.</p><h3 id="add-a-note" tabindex="-1">Add a note <a class="header-anchor" href="#add-a-note" aria-label="Permalink to &quot;Add a note&quot;">​</a></h3><p>Notes record what your team knows about a customer, such as a delivery preference or a phone call.</p><ol><li>In <strong>Add Note</strong>, write the note.</li><li>Tick <strong>Notify Customer</strong> to send the note to the customer by email. Leave it unticked to keep the note for your team.</li><li>Click <strong>Submit Note</strong>.</li></ol>',17)),r(s,{src:"/images/customer/customer-notes.png",alt:"Add Note card with a note typed and Notify Customer ticked"}),t[11]||(t[11]=n('<p>The notes are listed under the form, each with its date and whether the customer was notified. A note can&#39;t be edited or deleted after you submit it, and customers don&#39;t see notes in their account.</p><h3 id="edit-customer-details" tabindex="-1">Edit customer details <a class="header-anchor" href="#edit-customer-details" aria-label="Permalink to &quot;Edit customer details&quot;">​</a></h3><p>The <strong>Customer</strong> card shows the customer&#39;s name, <strong>Email</strong>, <strong>Phone</strong>, <strong>Gender</strong>, date of birth (<strong>DOB</strong>) and <strong>Group</strong>.</p><ol><li>Click <strong>Edit</strong> on the <strong>Customer</strong> card. The <strong>Edit Customer</strong> dialog opens.</li><li>Change the details.</li><li>Click <strong>Save customer</strong>.</li></ol>',4)),r(s,{src:"/images/customer/customer-edit.png",alt:"Edit Customer dialog with the Status and Suspended switches"}),t[12]||(t[12]=n('<p>The dialog has the fields of <strong>Create New Customer</strong> except <strong>Channel</strong>, and two switches:</p><table tabindex="0"><thead><tr><th>Switch</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>While it&#39;s on, the customer can sign in. While it&#39;s off, signing in shows <em>Your activation seeks admin approval</em>.</td></tr><tr><td><strong>Suspended</strong></td><td>While it&#39;s on, the customer can still sign in and browse, but can&#39;t check out: going to checkout returns them to the cart with <em>Your account has been suspended.</em></td></tr></tbody></table><p><strong>Gender</strong> is required. Customers who signed up on the storefront haven&#39;t chosen one, so pick one before you save.</p><h3 id="addresses" tabindex="-1">Addresses <a class="header-anchor" href="#addresses" aria-label="Permalink to &quot;Addresses&quot;">​</a></h3><p>The <strong>Addresses</strong> card lists the customer&#39;s saved addresses. The default one is marked <strong>Default Address</strong>.</p><p>To add an address:</p><ol><li>Click <strong>Create</strong> on the <strong>Addresses</strong> card. The <strong>Create Address</strong> panel opens.</li><li>Enter the <strong>Company Name</strong> and <strong>Vat ID</strong>, if the address has them.</li><li>Enter the <strong>First Name</strong>, <strong>Last Name</strong>, <strong>Email</strong>, <strong>Phone</strong> and <strong>Street Address</strong>.</li><li>Enter the <strong>City</strong> and <strong>Post Code</strong>.</li><li>Choose the <strong>Country</strong>, then the <strong>State</strong>. The state is a list when the country has states, and a text field otherwise.</li><li>Tick <strong>Default Address</strong> to make it the customer&#39;s default address.</li><li>Click <strong>Save Address</strong>.</li></ol>',7)),r(s,{src:"/images/customer/customer-address.png",alt:"Create Address panel with a street address in San Francisco"}),t[13]||(t[13]=n('<p>Each address also has:</p><ul><li><strong>Edit</strong>: change the address in the <strong>Edit Address</strong> panel.</li><li><strong>Delete</strong>: remove the address after you confirm.</li><li><strong>Set as Default</strong>: make it the default address. It appears on addresses that aren&#39;t the default.</li></ul><p>The number of <strong>Street Address</strong> lines is set in <a href="./../configure/address.html#information">Address</a>. Customers manage their own details and addresses on the storefront; see <a href="./customer-account.html">Customer Account</a>.</p>',3))])}const b=a(h,[["render",g]]);export{w as __pageData,b as default};
